import { spawnSync } from "node:child_process";
import { mkdtempSync, readFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const packageEsm = source => source
  .replace(
    "// @generated by protoc-gen-es v2.14.1\n",
    "// @generated by protoc-gen-es v2.14.1; packaged with explicit ESM import extensions\n",
  )
  .replace(/from "(\.\.?\/[^\"]+)";/g, (statement, specifier) =>
    specifier.endsWith(".js") ? statement : `from "${specifier}.js";`);
const temporary = mkdtempSync(join(tmpdir(), "acyclic-sdk-codegen-"));
try {
  const harnessProto = readFileSync(join(root, "proto/harness/v1/harness.proto"));
  const packagedHarnessProto = readFileSync(
    join(root, "rust/crates/harness/proto/harness/v1/harness.proto"),
  );
  if (!harnessProto.equals(packagedHarnessProto)) {
    throw new Error("packaged harness schema is stale; run bun run generate");
  }
  if (!readFileSync(join(root, "conformance/vectors/harness/native-wasm-event-v1.json")).equals(
    readFileSync(join(root, "rust/crates/harness/conformance/native-wasm-event-v1.json")),
  )) {
    throw new Error("packaged native/WASM conformance vector is stale; run bun run generate");
  }
  if (!readFileSync(join(root, "conformance/vectors/harness/error-mapping-v1.json")).equals(
    readFileSync(join(root, "rust/crates/harness/conformance/error-mapping-v1.json")),
  )) {
    throw new Error("packaged error-mapping vector is stale; run bun run generate");
  }
  const harnessSuite = JSON.parse(readFileSync(join(root, "conformance/vectors/core.json"), "utf8"));
  const nativeWasmCase = harnessSuite.cases.find(item => item.name === "native-wasm-replay-is-byte-equivalent");
  const nativeWasmVector = JSON.parse(
    readFileSync(join(root, "conformance/vectors/harness/native-wasm-event-v1.json"), "utf8"),
  );
  if (JSON.stringify(nativeWasmCase?.vector) !== JSON.stringify(nativeWasmVector)) {
    throw new Error("native/WASM fixture is not bound into the Harness suite");
  }

  const descriptor = join(temporary, "filesystem.bin");
  const executable = join(root, "node_modules", ".bin", process.platform === "win32" ? "buf.exe" : "buf");
  const objectsGenerated = spawnSync(
    executable,
    ["generate", "--output", temporary],
    { cwd: root, encoding: "utf8" },
  );
  if (objectsGenerated.status !== 0) {
    process.stderr.write(objectsGenerated.stdout ?? "");
    process.stderr.write(objectsGenerated.stderr ?? "");
    throw new Error(`Objects generation failed with status ${objectsGenerated.status ?? "unknown"}`);
  }
  for (const relative of ["objects/v1/objects_pb.js", "objects/v1/objects_pb.d.ts"]) {
    const fresh = readFileSync(join(temporary, "generated/typescript", relative));
    const committed = readFileSync(join(root, "generated/typescript", relative));
    if (!fresh.equals(committed)) throw new Error(`generated Objects TypeScript drift: ${relative}`);
  }
  const built = spawnSync(executable, ["build", "--path", "proto/filesystem", "-o", descriptor], {
    cwd: root,
    encoding: "utf8",
  });
  if (built.status !== 0) {
    process.stderr.write(built.stdout ?? "");
    process.stderr.write(built.stderr ?? "");
    throw new Error(`buf build failed with status ${built.status ?? "unknown"}`);
  }
  const committed = join(root, "rust/crates/filesystem/src/generated/acyclic-filesystem-v2.bin");
  if (!readFileSync(descriptor).equals(readFileSync(committed))) {
    throw new Error("filesystem descriptor is stale; run bun run generate");
  }

  const objectsDescriptor = join(temporary, "objects.bin");
  const objectsBuilt = spawnSync(executable, ["build", "--path", "proto/objects", "-o", objectsDescriptor], {
    cwd: root,
    encoding: "utf8",
  });
  if (objectsBuilt.status !== 0) {
    process.stderr.write(objectsBuilt.stdout ?? "");
    process.stderr.write(objectsBuilt.stderr ?? "");
    throw new Error(`buf build failed with status ${objectsBuilt.status ?? "unknown"}`);
  }
  const committedObjects = join(root, "rust/crates/objects/src/generated/acyclic-objects-v1.bin");
  if (!readFileSync(objectsDescriptor).equals(readFileSync(committedObjects))) {
    throw new Error("objects descriptor is stale; run bun run generate");
  }

  for (const relative of [
    "acyclic/objects/v1/acyclic.objects.v1.rs",
    "acyclic/objects/v1/acyclic.objects.v1.tonic.rs",
  ]) {
    const canonical = readFileSync(join(root, "generated/rust", relative));
    const packaged = readFileSync(join(root, "rust/crates/objects/src/generated", relative.split("/").at(-1)));
    if (!canonical.equals(packaged)) throw new Error(`packaged Objects Rust drift: ${relative}`);
  }

  {
    for (const file of ["acyclic.machines.v1.rs", "acyclic.machines.v1.tonic.rs"]) {
      const canonical = readFileSync(
        join(root, "generated/rust/acyclic/machines/v1", file),
        "utf8",
      );
      const packaged = readFileSync(
        join(root, "rust/crates/machines/src/generated", file),
        "utf8",
      );
      if (canonical !== packaged) throw new Error(`packaged Machines Rust drift: ${file}`);
    }
  }

  for (const relative of [
    "filesystem/v2/filesystem_pb.js",
    "filesystem/v2/filesystem_pb.d.ts",
    "harness/v1/harness_pb.js",
    "harness/v1/harness_pb.d.ts",
  ]) {
    const canonical = packageEsm(
      readFileSync(join(root, "generated/typescript", relative), "utf8"),
    );
    const packaged = readFileSync(
      join(root, "typescript/packages/filesystem/generated/proto", relative),
      "utf8",
    );
    if (canonical !== packaged) throw new Error(`packaged TypeScript drift: ${relative}`);
  }

  for (const relative of ["harness/v1/harness_pb.js", "harness/v1/harness_pb.d.ts"]) {
    const canonical = packageEsm(
      readFileSync(join(root, "generated/typescript", relative), "utf8"),
    );
    const packaged = readFileSync(
      join(root, "typescript/packages/harness/generated/proto", relative),
      "utf8",
    );
    if (canonical !== packaged) throw new Error(`packaged harness TypeScript drift: ${relative}`);
  }

  for (const relative of ["inference/v1/inference_pb.js", "inference/v1/inference_pb.d.ts"]) {
    const canonical = readFileSync(join(root, "generated/typescript", relative), "utf8");
    const packaged = readFileSync(
      join(root, "typescript/packages/inference/generated/proto", relative),
      "utf8",
    );
    if (canonical !== packaged) throw new Error(`packaged inference TypeScript drift: ${relative}`);
  }
} finally {
  rmSync(temporary, { recursive: true, force: true });
}
